window.VD=window.VD||{};window.VD["audi/a6-c5"]={"a6-c5-automatic-door-locking":"<p><strong>Purpose:</strong> Allows you to set automatic door locking from 15km/h, and unlocking when the key is removed.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “ <strong><strong>35 – Central lock </strong></strong>” .<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07</strong>”.  </p>\n<p><em>Add <strong>+32</strong> to the base value</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/codage-vcds_Audi-A4-B6-Confirmation-de-verrouillag-aea7b330.webp\"/></figure>","a6-c5-aux-in-socket-activation-retrofit":"<p><strong>Purpose </strong>: to activate the AUX-IN input. After installing the jack plug on the car radio connector or a Bluetooth kit (RNS-E or Generation II+ Concert, Chorus and Symphony), you can select AUX-IN in Source. For a BT module, if you have the AMI option, deactivate it.   (Retrofit)</p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 (For RNS-E !) :</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“37 – Navigation</strong>” .<br/><br/><strong>4 </strong>– Click on<strong>“Codage- 07</strong>”.</p>\n<p><strong>5</strong> – Modify the penultimate digit by adding <strong>4</strong>(e.g. replace <strong>xxxxx1x</strong>with <strong>xxxxx5x</strong>). </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_stg37_navi_codierung_auxin-f8795b14.webp\"/></figure>\n<hr/>\n<p><strong>Line 2 (For Generation II+ Concert, Chorus and Symphony</strong>)<strong>:</strong><br/><br/> 3 – Click on ” <strong>Select</strong> ” then click on<strong>“56 – Radio</strong>” .<br/><br/> 4<strong>– </strong>Click on<strong>“Codage- 07</strong>“.  </p>\n<p>5 – Modify the second digit by adding <strong>+4</strong> (0<strong>?</strong>x0xxx): <strong><br/><br/>+1 = Analog input (AUX)</strong><br/>+2 = Multifunction steering wheel<br/>+4 = Telephone</p>","a6-c5-change-odb-language":"<p><strong>Purpose </strong>: To change the language of the ODB. (from 2000).  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 04</strong></p>\n<p><em>Set the value according to the selected language</em></p>\n<p><em>1 = German</em><br/><em>2 = English</em><br/><em>3 = French</em><br/><em>4 = Italian</em><br/><em>5 = Spanish</em><br/><em>6 = Portuguese</em></p>","a6-c5-change-rns-e-startup-screen":"<p><strong>Purpose </strong>: to change the screen display at RNS-E start-up.  </p>\n<p><strong><em><em>CAUTION (Some RNS-E settings are directly related to the selected model. It is not recommended to change the vehicle model (Line1)). </em> </em></strong></p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“37 – Navigation</strong>” .<br/><br/><strong>4 </strong>– Click on<strong>“Codage- 07</strong>”.</p>\n<p><strong>5</strong> – Change the 2nd digit to the desired model. (ex: replace<strong>02xxxxx</strong>by<strong>01xxxxx</strong>to display the Lamborghini logo on an A3) </p>\n<p>– 1 Lamborghini Galardo<br/>– 2 <em>Audi A3 (8P)</em><br/>– 3 Audi A4 (8E) or Seat Exeo (3R)<br/>– 4 Audi A4 Cabriolet (8H)<br/>– 5 Audi A6 (4B)<br/>– 6 Audi TT (8J)<br/>– 7 Audi R8 (42)</p>\n<p><strong>Line 2:</strong><br/><br/> 3 – Click on “<strong>Select”</strong>, then click on<strong>“37 – Navigation</strong>” .<br/><br/> 4<strong>– </strong>Click on<strong>“Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 18</strong> (Start Screen) then set the value according to the desired display. <br/><br/>– 0 Standard<br/>– 1 Audi S3 (8P)<br/>– 2 Audi S4 (8E)<br/>– 3 Audi RS4, (8E)<br/>– 4 Audi TT (8J)<br/>– 5 Audi R8 (42)<br/>– 7 Audi TT S (8J)<br/>– 8 Audi TT RS (8J)<br/>– 9 Audi R8 GT (<em>42</em>)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8P0-035-193-G_Module37_Adaptation_Channel18-4f78df82.webp\"/></figure>","a6-c5-correction-of-odb-consumption-display":"<p><strong>Purpose</strong>: to correct the fuel consumption display on the on-board computer.  </p>\n<p><strong>Modification only possible on Mid/High range models</strong>. <br/><em>Note: modifications affect the display of instantaneous consumption, average consumption and fuel quantity.</em></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on <strong>“17 – Instruments”</strong>. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation- 10</strong>”.</p>\n<p><strong>5</strong> – Select <strong>Channel 03</strong> <em>“Consumption Correction”.</em></p>\n<p><em>Adjust consumption correction factor between 85% and 115%.</em> <em>(base value: 100)</em></p>\n<p><em>Example 1: Calculation based on volume per distance (e.g. l/100 km): DIS: 9.3 l/100 km. Actual: 9.8 l/100 km. (100, 9,8 / 9,73 ? 105,38) Channel 3 will be changed from 100 to 105 <br/>Example 2: Calculation based on volume distance (e.g. MPG is: DIS: 23 MPG. Actual: 24 MPG. (100, 23/24 and 95.83) Channel 3 will be changed from 100 to 96</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/correction-consommation-odb-d51db18e.webp\"/></figure>","a6-c5-delete-belt-alarm":"<p><strong>Purpose </strong>: To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt. (from 2000).  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07</strong>”.  </p>\n<p><em>The first two digits of the code (<strong>??</strong>xxxx) are used to modify the Instrument module options. To suppress the belt alarm, subtract <strong>2</strong> from these digits. </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","a6-c5-door-lock-unlock-confirmation-horn":"<p><strong>Purpose:</strong> Used to set door lock/unlock confirmation with beep (horn).  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “ <strong><strong>35 – Central lock </strong></strong>” .<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07</strong>”.  </p>\n<p>Add <strong>+1024</strong> to base value</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/codage-vcds_Audi-A4-B6-Confirmation-de-verrouillag-aea7b330.webp\"/></figure>","a6-c5-door-lock-unlock-confirmation-turn-signals":"<p><strong>Purpose: </strong>activates confirmation of vehicle locking/unlocking with turn signals.  </p>\n<p><strong>Procedure:</strong><br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>46 – Comfort Module.”</strong></p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – <em>Add <strong>+2</strong> to the existing coding </em>:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/codage-vcds_Audi-A4-B6-Confirmation-de-verrouillag-aea7b330.webp\"/></figure>","a6-c5-cruise-control-activation-retrofit":"<p><strong>Purpose:</strong> to activate the speed governor after retrofitting.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>01 – Motor</strong> “.</p>\n<p><strong>4</strong> – Click on “<strong>Access – 11</strong>” then enter the code “<strong><em><strong>11463</strong></em></strong>”  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/regulateur2-6871f13e.webp\"/></figure>","a6-c5-lock-rns-e-cd-dvd-eject-button":"<p><strong>Purpose</strong>: To lock/unlock the RNS-E’s CD/DVD eject button.  </p>\n<p><em>Protection against theft of your navigation DVD.  </em></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program. <strong><strong>37 – Navigation</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Choose <em><strong>Channel 67</strong> </em>then set the value to <strong>255</strong> <em>(Eject Button locked i.e. (Rental Car))</em></p>\n<p><em>Restart RNS-E.</em></p>\n<p>To eject the CD/DVD, set the value to <strong>0</strong> for normal use of the button, or <strong>1</strong> to eject it immediately.  </p>","a6-c5-opening-closing-windows-with-remote-control":"<p><strong>Purpose:</strong> to activate closing and opening of windows and sunroof with remote control.  </p>\n<p>Press and hold the buttons on the remote control or use the lock cylinder to open and close the windows and sunroof. <br/><br/><br/><strong>Procedure:</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>3</strong> – Click <strong>“Select</strong>,” then click <strong><strong>“35 – Central Locking”</strong></strong> .<br/><br/><strong>4 – </strong>Click on <strong>“Coding – 07</strong>” </p>\n<p>Add <strong>+64</strong> to base value</p>","a6-c5-selective-door-locking-unlocking":"<p><strong>Purpose: </strong>activates selective locking/unlocking of doors.  </p>\n<p><strong>Procedure:</strong><br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>46 – Comfort Module.”</strong></p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – <em>Add <strong>+4</strong> to the existing coding </em>:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/codage-vcds_Audi-A4-B6-Confirmation-de-verrouillag-aea7b330.webp\"/></figure>","a6-c5-show-climatronic-hidden-menu":"<p><strong>Purpose: Displays </strong>the Climatronic hidden menu.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/en-audiA6C5ClimatronicHiddenMenu-f43a93f2.webp\"/></figure>\n<p><strong>Display the instantaneous digital speed? It’s possible! </strong>  You don’t need to use your VCDS VAG-COM cable for this tutorial.</p>\n<p><strong>What is it used for?</strong></p>\n<p>In the hidden Audi Climatronic menu, you can easily access secret diagnostic readings such as battery voltage, vehicle speed, engine RPM, sensor readings, system DTCs, and much more.</p>\n<h3>Hidden single-zone Audi Climatronic menu procedure</h3>\n<ol>\n<li>Switch on the ignition and wait a few seconds for the Climatronic system to start. You can also switch on the engine. </li>\n<li>Press and hold the air recirculation button and the windshield ventilation button.</li>\n<li>Use the temperature buttons on the left to select the channel.</li>\n<li>Press <strong>the</strong> <strong>air</strong> <strong>recirculation</strong> button to read the value for the selected channel.</li>\n<li>Press the recirculation button again to return to channel selection.</li>\n<li>Switch off the ignition to exit the Audi A6 C5 Climatronic hidden diagnostics menu.</li>\n</ol>\n<h3>List of Hidden Channels in the Menus</h3>\n<ul>\n<li>1 – CTD</li>\n<li>2 – Value of the indoor temperature sensor at the head (G 86)</li>\n<li>3 – Reading from the interior temperature sensor on the instrument panel (G 56)</li>\n<li>4 – Value of the fresh air intake temperature sensor (G 89)</li>\n<li>5 – reading from the outside air temperature sensor (G 17), before</li>\n<li>6 – reading from the outside air temperature sensor</li>\n<li>7 – Temperature sensor reading at the fresh air blower (G 109)</li>\n<li>8 – Value of the potentiometer for the temperature-controlled flap motor (G 92)</li>\n<li>9 – Value of the temperature control authority’s damper</li>\n<li>10 – Specified value of the temperature control strategy</li>\n<li>11 – Setting for the center potentiometer for the flap motor (G 112)</li>\n<li>12 – Specified value of the center flap</li>\n<li>13 – Potentiometer value for low-cost/swing-arm motor (G 114)</li>\n<li>14 – Specified value for the Footwell/Defroster Flap</li>\n<li>15 – Potentiometer setting for the air-fed chaff motor (G 113)</li>\n<li>16 – Specified value of the air flow damper</li>\n<li>17 – speed (km/h)</li>\n<li>18 – Air blower voltage (volts)</li>\n<li>19 – Specified voltage of the fresh air blower (volts)</li>\n<li>20 – A/C Compressor Voltage (volts)</li>\n<li>21 – Low-Voltage Event Counter</li>\n<li>22 – Status of the A/C refrigerant high-pressure switch cycle (F 118)</li>\n<li>23 – cycles of the A/C high-pressure refrigerant switch (F 118)</li>\n<li>24 – switch cycles, no absolute fluctuation</li>\n<li>25 – Kick-Down Switch</li>\n<li>26 – Engine Coolant Temperature (ECT) Warning Light</li>\n<li>27 – Engine Speed (RPM)</li>\n<li>29 – A/C Compressor Speed (RPM)</li>\n<li>30 – SW Version</li>\n<li>32 – malfunction counter, temperature control flap</li>\n<li>33 – malfunction counter, center flap</li>\n<li>34 – Malfunction Indicator Light, Footwell/Defroster Flap</li>\n<li>35 – Malfunction Counter, Airflow Map</li>\n<li>36 – Cold Shut-off, Temperature Control Valve (G 92)</li>\n<li>37 – Hot stop, temperature controller, temperature flap motor (G 92), maximum stop</li>\n<li>38 – Cold Shutdown, Motor-Driven Valve (G 112)</li>\n<li>39 – Hot Stop, Central Potentiometer for Flap Motor (G 112)</li>\n<li>40 – Cold Shutdown, Footwell Motor Potentiometer/Fold-Down Hood (G114)</li>\n<li>41 – Hot Stop, Foot/Arrow-Type Motor Potentiometer (G114)</li>\n<li>42 – Cold Shutdown, Air Flow Diagram: Engine Map (G 113)</li>\n<li>43 – Hot shutdown, airflow diagram for the engine on the airflow chart (G 113)</li>\n<li>44 – Vehicle Operating Cycle Counter</li>\n<li>45 – Calculated indoor temperature</li>\n<li>46 – outdoor temperature, filtered, for control purposes</li>\n<li>47 – outdoor temperature in degrees C</li>\n<li>48 – outdoor temperature</li>\n<li>49 – Operational countermeasure for the speed signal</li>\n<li>50 – rest time (in minutes)</li>\n<li>51 – Engine Coolant Temperature</li>\n<li>52 – Graphic Channel 1 – The conditions under which the A/C compressor shuts off are indicated by illuminated segments on the “88.8” display.</li>\n<li>53 – Graphic Channel 2 – The electrical outputs of the climate control system are indicated by illuminated segments on the “88.8” display.</li>\n<li>54 – Control Characteristics</li>\n<li>55 – Outdoor temperature for the SIF/DIS</li>\n<li>56 – temperature in degrees Celsius, from the interior temperature sensor in the hair salon (G 86)</li>\n<li>57 – Temperature in degrees Celsius from the interior temperature sensor in the instrument panel (G 56)</li>\n<li>58 – temperature in degrees Celsius, as measured by the fresh air intake temperature sensor (G 89)</li>\n<li>59 – temperature in degrees Celsius, based on outside (ambient) air; temperature sensor (G 17), front</li>\n<li>60 – temperature in degrees Celsius, as measured by the ambient temperature sensor at the fresh air blower (G 109)</li>\n<li>61 – software version</li>\n<li>86 – Control Display</li>\n</ul>","a6-c5-speed-limit-display-rns-e":"<p><strong>Purpose </strong>: to display the speed limit on the RNS-E navigation screen.  </p>\n<p><strong><em>ATTENTION: requires RNS-E version 193</em></strong></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong><br/></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on<strong>“37 – Navigation</strong>”.<br/><br/> 4<strong>– </strong>Click on<strong>“Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 17</strong> (Speed Display) then set the value according to the desired display. <br/><br/>Set the value according to the desired display<em><br/>0</em><em>– no option (display disabled)<br/></em> 1<em>– option on, off (speed display)<br/></em> 2<em>– option on, off, 5km/h, 10km/h, 15km/h, 20km/h (speed display + overrun warning)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8P0-035-193-G_Module37_Adaptation_Channel17-6e590288.webp\"/></figure>\n<p><em>Don’t forget to restart the RNS-E, by pressing the power button for more than 40s.</em></p>"};
